<script lang="ts">
 import {tick,type Snippet} from 'svelte';
 import DragHandleIcon from './DragHandleIcon.svelte';
 import {localization} from '$lib/localization';
 let {ids,label,labelFor,disabled=false,canDrag=()=>true,groupFor=()=>'',table=false,header,children,onreorder}:{ids:number[];label:string;labelFor:(id:number)=>string;disabled?:boolean;canDrag?:(id:number)=>boolean;groupFor?:(id:number)=>string;table?:boolean;header?:Snippet;children:Snippet<[number]>;onreorder:(ids:number[],moved:number,target:number)=>void}=$props();
 const owner=$props.id();let root=$state<HTMLElement>(),active=$state<number|null>(null),preview=$state<number[]>([]),target=$state<number|null>(null),pointer=$state<number|null>(null),announcement=$state('');
 let shown=$derived(active===null?ids:preview);
 function start(id:number){if(disabled||!canDrag(id))return;active=id;target=id;preview=[...ids];}
 function move(over:number){if(active===null||over===active||!canDrag(over)||groupFor(over)!==groupFor(active))return;const next=[...preview],from=next.indexOf(active),to=next.indexOf(over);if(from<0||to<0)return;next.splice(from,1);next.splice(to,0,active);preview=next;target=over;announcement=`${labelFor(active)}: ${to+1} / ${next.length}`;if(pointer===null){const moving=active;void tick().then(()=>root?.querySelector<HTMLButtonElement>(`[data-sort-grip="${moving}"]`)?.focus({preventScroll:true}));}}
 function finish(commit:boolean){if(active===null)return;const moved=active,over=target,next=[...preview];active=null;pointer=null;target=null;if(commit&&over!==null&&next.join()!==ids.join())onreorder(next,moved,over);}
 function down(e:PointerEvent,id:number){if(e.button!==0||disabled||!canDrag(id))return;e.preventDefault();start(id);pointer=e.pointerId;const handle=e.currentTarget as HTMLElement;handle.focus({preventScroll:true});handle.setPointerCapture(e.pointerId);}
 function drag(e:PointerEvent){if(pointer!==e.pointerId||active===null)return;const row=document.elementFromPoint(e.clientX,e.clientY)?.closest<HTMLElement>('[data-sortable-item]');if(!row||row.dataset.sortableOwner!==owner||!root?.contains(row))return;const over=Number(row.dataset.sortableItem),from=preview.indexOf(active),to=preview.indexOf(over),box=row.getBoundingClientRect();if(from<to&&e.clientY<box.top+box.height/2||from>to&&e.clientY>box.top+box.height/2)return;move(over);if(e.clientY<70)window.scrollBy(0,-16);else if(e.clientY>innerHeight-70)window.scrollBy(0,16);}
 function key(e:KeyboardEvent,id:number){if(disabled||!canDrag(id))return;if([' ','Enter'].includes(e.key)){e.preventDefault();if(active===id)finish(true);else start(id);}else if(e.key==='Escape'){e.preventDefault();finish(false);}else if(active===id&&['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const peers=preview.filter(n=>canDrag(n)&&groupFor(n)===groupFor(id)),at=peers.indexOf(id),index=e.key==='Home'?0:e.key==='End'?peers.length-1:Math.max(0,Math.min(peers.length-1,at+(e.key==='ArrowUp'?-1:1)));move(peers[index]);}}
</script>
<svelte:window onpointermove={drag} onpointerup={e=>{if(pointer===e.pointerId)finish(true);}} onpointercancel={e=>{if(pointer===e.pointerId)finish(false);}} onpointerdown={e=>{if(active!==null&&pointer===null&&!root?.contains(e.target as Node))finish(false);}}/>
{#snippet grip(id:number)}<button class="sort-grip" data-sort-grip={id} type="button" aria-label={`${label}: ${labelFor(id)}`} title={`${label}: ${labelFor(id)}`} aria-pressed={active===id} aria-describedby={owner+'-hint'} disabled={disabled||!canDrag(id)} onpointerdown={e=>down(e,id)} onkeydown={e=>key(e,id)}><DragHandleIcon/></button>{/snippet}
<span class="sr-only" id={owner+'-hint'}>{$localization.displayLanguage==='ja'?'ドラッグで順番を変更。SpaceまたはEnterで選択し、方向キーで移動、Spaceで確定、Escapeで取り消します。':'Drag to reorder. Space or Enter to pick up, arrow keys to move, Space to drop, Escape to cancel.'}</span><span class="sr-only" role="status" aria-live="polite">{announcement}</span>
{#if table}
 <table bind:this={root} class="sortable-table"><thead><tr><th class="grip-cell"><span class="sr-only">{label}</span></th>{#if header}{@render header()}{/if}</tr></thead><tbody>{#each shown as id (id)}<tr data-sortable-owner={owner} data-sortable-item={id} class:sorting={active===id}><td class="grip-cell">{@render grip(id)}</td>{@render children(id)}</tr>{/each}</tbody></table>
{:else}
 <div bind:this={root} class="sortable-list">{#each shown as id (id)}<div class="sortable-row" data-sortable-owner={owner} data-sortable-item={id} class:sorting={active===id}>{@render grip(id)}<div class="sortable-content">{@render children(id)}</div></div>{/each}</div>
{/if}
<style>
 .sortable-list{display:grid;gap:10px;min-width:0}.sortable-row{display:grid;grid-template-columns:32px minmax(0,1fr);gap:8px;align-items:center;min-width:0}.sortable-content{min-width:0}.sort-grip{display:grid;place-items:center;width:32px;height:36px;padding:4px;border:0;border-radius:var(--sph-radius-4px);background:transparent;color:var(--muted);cursor:grab;touch-action:none;user-select:none}.sort-grip:active{cursor:grabbing}.sort-grip:focus-visible{outline:2px solid var(--action-primary);outline-offset:2px}.sort-grip:disabled{opacity:.3;cursor:default}.sorting{outline:2px solid var(--action-primary);outline-offset:2px;border-radius:var(--sph-radius-4px);background:var(--surface-hover)}.sortable-table{width:100%;border-collapse:collapse}.grip-cell{width:36px;padding:4px;vertical-align:middle}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}@media(max-width:700px){.sort-grip{height:44px}}
</style>
